#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Roteiro do primeiro deploy do homolog (issues 23 e 28, docs/deploy.md).
#
#   infra/homolog_roteiro.sh
#
# Rode no seu terminal, nunca dentro de uma sessão de agente: os valores
# gerados aqui vão para a área de transferência e para o Dokploy, e não devem
# aparecer em nenhuma conversa. O roteiro não grava nada em arquivo.

DOKPLOY="https://infra.dynatech.systems"
API="https://saturday-homolog.dynatech.systems"
PAINEL="https://painel-saturday-homolog.dynatech.systems"
ONDE_COLAR="Dokploy → projeto Saturday → ambiente homolog → stack saturday → aba Environment"

# copiar: põe a entrada padrão na área de transferência, sem mostrar na tela.
copiar() {
  if   command -v pbcopy   >/dev/null 2>&1; then pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then wl-copy
  elif command -v xclip    >/dev/null 2>&1; then xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then clip.exe
  else return 1; fi
}

# gerar NOME: sorteia 32 bytes, guarda em $NOME (só na memória deste processo)
# e copia para a área de transferência.
gerar() {
  local nome="$1" valor
  valor=$(openssl rand -hex 32)
  printf -v "$nome" '%s' "$valor"
  if printf '%s' "$valor" | copiar; then
    printf '  %s✓%s %s gerado e copiado (não aparece na tela)\n' "$GREEN" "$RESET" "$nome"
  else
    warn "sem área de transferência neste terminal; o valor de $nome vai aparecer abaixo:"
    say "$valor"
  fi
}

run_wizard() {

# O roteiro não lê nem escreve .env: nenhum valor fica em arquivo.
ENV_FILE=/dev/null
TOTAL_STAGES=9
MINIO_CONSOLE=""
SATURDAY_WHATSAPP_VERIFY_TOKEN=""

command -v openssl >/dev/null 2>&1 || { echo "falta o openssl neste terminal" >&2; exit 1; }

banner "Saturday: primeiro deploy do homolog"

# ── 1. Bucket de anexos ────────────────────────────────────────────────────
stage "Bucket de anexos (MinIO)"
say "Um bucket privado só do homolog, no mesmo MinIO do dev."
ask MINIO_CONSOLE "Endereço do console do MinIO (https://...):"
open_url "$MINIO_CONSOLE"
step "Crie o bucket saturday-homolog, privado."
step "Ligue o versionamento do bucket."
step "Crie a regra de ciclo de vida: expirar versões antigas (não as atuais) em 30 dias."
step "Crie uma chave de acesso que só enxergue esse bucket."
note "Pelo cliente mc, os três primeiros são:"
note "  mc mb APELIDO/saturday-homolog"
note "  mc version enable APELIDO/saturday-homolog"
note "  mc ilm rule add --noncurrent-expire-days 30 APELIDO/saturday-homolog"
note "A chave restrita a um bucket não foi conferida na documentação do MinIO:"
note "use o caminho que você usou para a chave do dev."
pause "Bucket e chave prontos? Enter para ir ao Dokploy"
open_url "$DOKPLOY"
say "Cole em: $ONDE_COLAR"
step "SATURDAY_S3_ENDPOINT   = endereço da API S3 do MinIO (não o do console)"
step "SATURDAY_S3_BUCKET     = saturday-homolog"
step "SATURDAY_S3_REGIAO     = a mesma do dev"
step "SATURDAY_S3_ACCESS_KEY = a chave de acesso nova"
step "SATURDAY_S3_SECRET_KEY = o segredo da chave nova"
pause "Cinco variáveis coladas e salvas? Enter"

# ── 2. Bucket de backups ───────────────────────────────────────────────────
stage "Bucket de backups e destino no Dokploy"
say "Um bucket privado só para os backups do Postgres, com chave própria."
open_url "$MINIO_CONSOLE"
step "Crie o bucket saturday-backups, privado."
step "Crie uma chave de acesso que só enxergue esse bucket."
pause "Bucket e chave prontos? Enter para ir ao Dokploy"
open_url "$DOKPLOY"
step "Settings → S3 Destinations → novo destino com o nome saturday-backups."
step "Preencha com o endereço da API S3, o bucket saturday-backups e a chave nova."
note "O nome precisa ser exatamente saturday-backups: é o que o guia de deploy usa."
note "O agendamento de cada Postgres fica com o agente, depois da sua confirmação."
pause "Destino saturday-backups salvo? Enter"

# ── 3. App da Meta ─────────────────────────────────────────────────────────
stage "App da Meta do homolog"
say "Um app só do homolog, com o número de teste que a Meta cria junto."
warn "Os nomes dos menus da Meta mudam; se um não existir, procure o equivalente."
open_url "https://developers.facebook.com/apps/"
step "Crie um app novo com o caso de uso do WhatsApp (por exemplo, Saturday Homolog)."
step "Em WhatsApp → API Setup, anote o Phone number ID do número de teste."
step "Em App settings → Basic, revele e copie o App secret."
pause "Phone number ID e App secret em mãos? Enter para o token permanente"
say "O token da tela API Setup vence em horas. O que vale é o de um usuário do sistema."
open_url "https://business.facebook.com/settings/system-users"
step "Adicione um usuário do sistema (papel Admin)."
step "Atribua a ele o app novo, com Manage app, e a conta do WhatsApp, com controle total."
step "Gere o token escolhendo o app e as permissões business_management,"
step "  whatsapp_business_management e whatsapp_business_messaging. Copie o token."
pause "Token copiado? Enter para ir ao Dokploy"
open_url "$DOKPLOY"
say "Cole em: $ONDE_COLAR"
step "SATURDAY_WHATSAPP_TOKEN      = o token do usuário do sistema"
step "SATURDAY_WHATSAPP_APP_SECRET = o App secret"
step "SATURDAY_WHATSAPP_NUMEROS    = o Phone number ID do número de teste"
pause "Três variáveis coladas e salvas? Enter"

# ── 4. Valores aleatórios ──────────────────────────────────────────────────
stage "Quatro valores aleatórios"
say "Cada valor sai do openssl direto para a área de transferência."
say "Cole em: $ONDE_COLAR"
open_url "$DOKPLOY"
gerar SATURDAY_API_KEY
pause "Colou em SATURDAY_API_KEY? Enter para o próximo"
gerar SATURDAY_SESSAO_SEGREDO
pause "Colou em SATURDAY_SESSAO_SEGREDO? Enter para o próximo"
gerar SATURDAY_WHATSAPP_VERIFY_TOKEN
pause "Colou em SATURDAY_WHATSAPP_VERIFY_TOKEN? Enter para o próximo"
note "O verify token fica na memória deste roteiro até a etapa 8."
gerar SATURDAY_GRANATECH_WEBHOOK_TOKEN
step "Cole em SATURDAY_GRANATECH_WEBHOOK_TOKEN."
step "Passe o mesmo valor à Granatech e peça o webhook em:"
say "    $API/webhooks/granatech   (header x-webhook-token)"
pause "Colado no Dokploy e enviado à Granatech? Enter"
unset SATURDAY_API_KEY SATURDAY_SESSAO_SEGREDO SATURDAY_GRANATECH_WEBHOOK_TOKEN

# ── 5. Chaves que você já tem ──────────────────────────────────────────────
stage "Chaves que você já tem"
say "Copie de onde você as guarda e cole em: $ONDE_COLAR"
step "SATURDAY_OPENROUTER_API_KEY"
step "SATURDAY_LLM_MODEL e SATURDAY_VISION_MODEL (os mesmos do dev)"
step "SATURDAY_TRANSCRICAO_API_KEY e SATURDAY_TRANSCRICAO_MODELO (sem eles, áudio vira pedido de texto)"
step "SATURDAY_GRANATECH_CHAVE_API (a da api-dev)"
step "SATURDAY_DATABASE_URL, com a senha do Postgres do homolog:"
say "    postgresql://saturday:<senha>@<appName-do-postgres>:5432/saturday"
note "A senha e o appName estão na página do saturday-postgres-homolog, no Dokploy."
pause "Todas coladas e salvas? Enter"

# ── 6. Conferência antes do deploy ─────────────────────────────────────────
stage "Conferência antes do deploy"
say "O primeiro deploy sobe só o essencial. Confira na aba Environment:"
step "SATURDAY_ENVIRONMENT=homolog e SATURDAY_IMAGEM_TAG=homolog"
step "SATURDAY_REDE_DADOS=saturday-homolog-dados e COMPOSE_PROFILES vazio"
step "SATURDAY_GRANATECH_ATIVO=true e SATURDAY_GRANATECH_PROPOSTA_ATIVA=false"
step "SATURDAY_GRANATECH_BASE_URL=https://api-dev.granatech.com.br"
step "SATURDAY_EVOLUTION_ATIVO, SATURDAY_C6_ATIVO e SATURDAY_ICRED_ATIVO em false"
step "SATURDAY_GRANATECH_SIMULADOR_URL vazia"
if ! confirm "Tudo confere?"; then
  warn "Acerte no Dokploy e rode o roteiro de novo: as etapas já feitas é só confirmar."
  exit 1
fi
say "Agora peça o deploy ao agente, na conversa:"
say "    pode fazer o deploy do homolog"
note "Ele confirma o alvo por nome e ID antes de disparar (decisão 0005)."
pause "Pediu o deploy? Enter para esperar a API subir"

# ── 7. Espera do deploy ────────────────────────────────────────────────────
stage "Esperando a API do homolog"
say "Consultando $API/health a cada 15 segundos. Ctrl-C para desistir."
until curl -fsS --max-time 10 "$API/health" >/dev/null 2>&1; do
  printf '  %s… ainda não respondeu%s\n' "$DIM" "$RESET"
  sleep 15
done
printf '  %s✓%s a API respondeu\n' "$GREEN" "$RESET"
pause "Enter para cadastrar o webhook da Meta"

# ── 8. Webhook da Meta ─────────────────────────────────────────────────────
stage "Webhook da Meta"
if [[ -n "$SATURDAY_WHATSAPP_VERIFY_TOKEN" ]] && printf '%s' "$SATURDAY_WHATSAPP_VERIFY_TOKEN" | copiar; then
  say "O verify token da etapa 4 está de novo na área de transferência."
else
  warn "Copie o SATURDAY_WHATSAPP_VERIFY_TOKEN da aba Environment do Dokploy."
fi
open_url "https://developers.facebook.com/apps/"
step "No app do homolog: WhatsApp → Configuration → Webhooks."
step "Callback URL: $API/webhooks/whatsapp"
step "Verify token: cole o valor e clique em Verify and save."
step "Assine o campo messages."
pause "Webhook verificado e messages assinado? Enter"
unset SATURDAY_WHATSAPP_VERIFY_TOKEN
printf '' | copiar || true

# ── 9. Primeiro gestor ─────────────────────────────────────────────────────
stage "Primeiro gestor do painel"
open_url "$DOKPLOY"
step "No stack saturday do homolog, abra o terminal do container api e rode:"
say "    saturday criar-usuario --email <seu e-mail> --perfil gestor --nome \"<seu nome>\""
note "O comando pede a senha no próprio terminal, sem mostrar."
pause "Usuário criado? Enter para abrir o painel"
open_url "$PAINEL"
step "Entre com o e-mail e a senha que você definiu no comando."
pause "Entrou no painel? Enter para terminar"

finish
say "Falta o agente: agendar os backups do dev e do homolog e rodar o teste de restauração."
}

run_wizard "$@"; exit
